  });

  it('应显示论坛数据统计', () => {
    renderFooter();

    expect(screen.getByText(/今日帖数/)).toBeInTheDocument();
    expect(screen.getByText(/昨日帖数/)).toBeInTheDocument();
    expect(screen.getByText(/最高日帖数/)).toBeInTheDocument();
    expect(screen.getByText(/论坛主题/)).toBeInTheDocument();
    expect(screen.getByText(/总帖数/)).toBeInTheDocument();
    expect(screen.getByText(/注册会员/)).toBeInTheDocument();
  });

  it('应显示友情链接', () => {
    renderFooter();

    expect(screen.getByText('关于我们')).toBeInTheDocument();
    expect(screen.getByText('浙江大学')).toBeInTheDocument();
    expect(screen.getByText('联系管理员')).toBeInTheDocument();
    expect(screen.getByText('论坛条例')).toBeInTheDocument();
  });

  it('"浙江大学"链接应包含安全属性', () => {
    renderFooter();

    const zjuLink = screen.getByText('浙江大学');
    expect(zjuLink).toHaveAttribute('target', '_blank');
    expect(zjuLink).toHaveAttribute('rel', 'noopener noreferrer');
  });

  it('应显示 Powered by 信息', () => {
    renderFooter();

    expect(
      screen.getByText(/Powered by React \+ Spring Boot/)
    ).toBeInTheDocument();
  });

  it('应包含统计数值', () => {
    renderFooter();

    // 检查数据统计区有数值显示
    expect(screen.getByText('124')).toBeInTheDocument();
    expect(screen.getByText('482')).toBeInTheDocument();
  });
});

import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import BoardCard from '../../components/BoardCard';
import type { Category } from '../../api/category';

describe('BoardCard', () => {
  const mockCategory: Category = {
    id: 1,
    name: '技术交流',
    description: '编程、算法与技术讨论',
    sortOrder: 1,
    createdAt: '2025-01-01T00:00:00Z',
    postCount: 128,
    todayPostCount: 15,
  };

  const renderBoardCard = (category = mockCategory, onClick?: (id: number) => void) => {
    return render(<BoardCard category={category} onClick={onClick} />);
  };

  it('应显示版块名称', () => {
    renderBoardCard();

    expect(screen.getByText('技术交流')).toBeInTheDocument();
  });

  it('应显示版块描述', () => {
    renderBoardCard();

    expect(screen.getByText('编程、算法与技术讨论')).toBeInTheDocument();
  });

  it('应显示帖子统计（主题数）', () => {
    renderBoardCard();

    expect(screen.getByText('128')).toBeInTheDocument();
  });

  it('应显示今日帖子数', () => {
    renderBoardCard();

    expect(screen.getByText('15')).toBeInTheDocument();
  });

  it('应显示帖子总数 badge', () => {
    renderBoardCard();

    expect(screen.getByText('128 贴')).toBeInTheDocument();
  });

  it('无描述时应显示默认文本', () => {
    const catWithoutDesc = { ...mockCategory, description: '' };
    renderBoardCard(catWithoutDesc);

    expect(screen.getByText('暂无描述。')).toBeInTheDocument();
  });

  it('点击应触发 onClick 回调并传入版块 ID', async () => {
    const handleClick = vi.fn();
    renderBoardCard(mockCategory, handleClick);

    const card = screen.getByText('技术交流').closest('.cc98-board-card');
    expect(card).toBeInTheDocument();

    if (card) {
      await userEvent.click(card);
    }

    expect(handleClick).toHaveBeenCalledTimes(1);
    expect(handleClick).toHaveBeenCalledWith(1);
  });

  it('应渲染 Font Awesome 图标', () => {
    renderBoardCard();

    // id=1 → fa-heartbeat
    const icon = document.querySelector('.cc98-board-icon i');
    expect(icon).toBeInTheDocument();
    expect(icon).toHaveClass('fa-heartbeat');
  });

  it('不同 ID 应渲染不同图标', () => {
    const cat2 = { ...mockCategory, id: 2 };
    const { unmount } = renderBoardCard(cat2);

    // id=2 → fa-gamepad
    const icon = document.querySelector('.cc98-board-icon i');
    expect(icon).toHaveClass('fa-gamepad');

    unmount();
  });
});

import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router-dom';
import TopicTable from '../../components/TopicTable';
