    vi.clearAllMocks();
  });

  const mockPosts: Post[] = [
    {
      id: 1,
      title: '欢迎来到 CC91 论坛',
      content: '这是第一篇帖子',
      authorId: 1,
      authorUsername: 'admin',
      categoryId: 1,
      categoryName: '站务',
      status: 'STICKY',
