      updatedAt: '2025-06-01T10:00:00Z',
      viewCount: 256,
      commentCount: 12,
    },
    {
      id: 2,
      title: 'React 入门教程分享',
      content: 'React 学习笔记',
      authorId: 2,
      authorUsername: 'user',
      categoryId: 2,
      categoryName: '技术',
      status: 'APPROVED',
