      content: '热门内容',
      authorId: 3,
      authorUsername: 'editor',
      categoryId: 3,
      categoryName: '灌水',
      status: 'APPROVED',
      createdAt: '2025-06-03T08:00:00Z',
      updatedAt: '2025-06-03T08:00:00Z',
      viewCount: 500,
      commentCount: 20,
    },
  ];

  const renderTopicTable = (posts: Post[] = mockPosts) => {
    return render(
      <MemoryRouter>
        <TopicTable posts={posts} />
      </MemoryRouter>
    );
  };

